import { JWT } from "google-auth-library";
import { GoogleSpreadsheet } from "google-spreadsheet";
import type { Exporter, RenderedValue } from "./types";
import { drive as Drive } from "@googleapis/drive";

type NewDocumentInit = { title: string; folderId?: string };
type ExistingDocumentInit = { spreadsheetId: string };
type InitArg = NewDocumentInit | ExistingDocumentInit;
export const GoogleSheetsExporter: Exporter<
  InitArg,
  Promise<GoogleSpreadsheet>
> = () => {
  const auth = new JWT({
    // env var values here are copied from service account credentials generated by google
    // see "Authentication" section in docs for more info
    email: process.env.GOOGLE_SERVICE_ACCOUNT_EMAIL,
    key: process.env.GOOGLE_PRIVATE_KEY?.replace(/\\n/g, "\n"),
    subject: process.env.MY_GOOGLE_ACCOUNT_EMAIL,
    scopes: [
      "https://www.googleapis.com/auth/spreadsheets",
      "https://www.googleapis.com/auth/drive.file",
    ],
  });

  const createSheet = async ({ title, folderId }: NewDocumentInit) => {
    const sheet = await GoogleSpreadsheet.createNewSpreadsheetDocument(auth, {
      title,
    });
    if (folderId) {
      const drive = Drive({ version: "v3", auth });
      await drive.files.update({
        fileId: sheet.spreadsheetId,
        addParents: folderId,
      });
    }
    return sheet;
  };

  const getSheet = ({ spreadsheetId }: ExistingDocumentInit) =>
    new GoogleSpreadsheet(spreadsheetId, auth);

  const getInitData = (arg: InitArg): InitArg =>
    process.env.EVAL_SPREADSHEET_ID
      ? { spreadsheetId: process.env.EVAL_SPREADSHEET_ID }
      : arg;

  const init = async (arg: InitArg) => {
    const initData = getInitData(arg);
    const doc = await ("spreadsheetId" in initData
      ? getSheet(initData)
      : createSheet(initData));

    process.env.EVAL_SPREADSHEET_ID = doc.spreadsheetId;

    return doc;
  };

  const getActiveDoc = async () => {
    const spreadsheetId = process.env.EVAL_SPREADSHEET_ID;
    if (!spreadsheetId)
      throw new Error(`process.env.EVAL_SPREADSHEET_ID was not found`);
    const sheet = getSheet({ spreadsheetId });
    await sheet.loadInfo();
    return sheet;
  };

  type SheetsRow = Record<string, string | number | boolean>;
  let buffer: Array<SheetsRow> = [];

  return {
    init,
    start: async ({ title, fields }) => {
      const doc = await getActiveDoc();
      const sheet =
        doc.sheetsByTitle[title] ||
        (await doc.addSheet({ title, headerValues: fields }));

      doc.sheetsByTitle.Sheet1?.delete();

      const flush = async () => {
        if (!buffer.length) return;

        const temp = buffer;
        buffer = [];
        await sheet.addRows(temp);
      };

      return {
        report: async ({ result }) => {
          const row = Object.fromEntries(
            Object.entries(result)
              .map((el) => el as [string, RenderedValue])
              .map(([key, value]) => [key, value ?? ""])
          );

          buffer.push(row);

          if (buffer.length >= 100) await flush();
        },
        flush,
      };
    },
  };
};
